import { registerWebComponents } from '@domg-wc/common';
import { VlPillComponent } from '@domg-wc/components/block';

registerWebComponents([VlPillComponent]);

const pill = document.querySelector('vl-pill');
// close volgt op een klik op het kruisje van een pill met closable. Het event bubbelt niet, en de pill verwijdert
// zichzelf niet.
pill.addEventListener('close', (event) => {
    console.log('close', event);
});
// check volgt op het aan- of uitvinken van een pill met checkable; event.detail.checked geeft de nieuwe toestand.
pill.addEventListener('check', (event) => {
    console.log(event.detail.checked);
});
// click volgt op een klik op een pill met clickable.
pill.addEventListener('click', (event) => {
    console.log('click', event);
});
